function createBaseMediaResolutionPriceEntry(): MediaResolutionPriceEntry {
  return {
    resolution: "",
    size: "",
    withAudio: false,
    withVideoInput: false,
    fixedOutputTokens: 0n,
    ratePerUnitUsdDec: "",
    unitName: "",
  };
}

